'use strict';

// Source: js/profile-store.js
const PROFILE_DB_NAME = 'gitaverse-profiles';
const PROFILE_DB_VERSION = 2;
const PROFILE_STORE = 'profiles';
const SETTINGS_STORE = 'settings';
const RESUME_STORE = 'resumePoints';

function requestResult(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('The profile database could not be opened.'));
  });
}

function transactionDone(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = resolve;
    transaction.onerror = () => reject(transaction.error || new Error('The profile change could not be saved.'));
    transaction.onabort = () => reject(transaction.error || new Error('The profile change was cancelled.'));
  });
}

function openProfileDatabase() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(PROFILE_DB_NAME, PROFILE_DB_VERSION);
    request.onupgradeneeded = () => {
      const database = request.result;
      if (!database.objectStoreNames.contains(PROFILE_STORE)) {
        database.createObjectStore(PROFILE_STORE, { keyPath: 'pid', autoIncrement: true });
      }
      if (!database.objectStoreNames.contains(SETTINGS_STORE)) {
        database.createObjectStore(SETTINGS_STORE, { keyPath: 'key' });
      }
      if (!database.objectStoreNames.contains(RESUME_STORE)) {
        database.createObjectStore(RESUME_STORE, { keyPath: 'pid' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Local profile storage is unavailable.'));
  });
}

function randomAnalyticsId() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') return globalThis.crypto.randomUUID();
  const bytes = new Uint8Array(16);
  globalThis.crypto.getRandomValues(bytes);
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
}

class ProfileStore {
  constructor() {
    this.database = null;
  }

  async open() {
    if (!this.database) this.database = await openProfileDatabase();
    return this;
  }

  async list() {
    await this.open();
    const transaction = this.database.transaction(PROFILE_STORE, 'readonly');
    const profiles = await requestResult(transaction.objectStore(PROFILE_STORE).getAll());
    return profiles.sort((left, right) => left.pid - right.pid);
  }

  async get(pid) {
    await this.open();
    if (!Number.isInteger(Number(pid))) return null;
    const transaction = this.database.transaction(PROFILE_STORE, 'readonly');
    return (await requestResult(transaction.objectStore(PROFILE_STORE).get(Number(pid)))) || null;
  }

  async save(input) {
    await this.open();
    const name = String(input.name || '').trim();
    if (!name) throw new Error('Enter a profile name.');
    const now = new Date().toISOString();
    const existing = input.pid ? await this.get(input.pid) : null;
    const profile = {
      ...(existing || {}),
      name,
      dob: input.dob,
      gender: input.gender || '',
      language: input.language === 'kn' ? 'kn' : 'en',
      photo: input.photo || '',
      analyticsConsent: Boolean(input.analyticsConsent),
      analyticsProfileId: existing?.analyticsProfileId || randomAnalyticsId(),
      createdAt: existing?.createdAt || now,
      updatedAt: now
    };
    if (existing) profile.pid = existing.pid;
    const transaction = this.database.transaction(PROFILE_STORE, 'readwrite');
    const request = transaction.objectStore(PROFILE_STORE).put(profile);
    const pid = await requestResult(request);
    await transactionDone(transaction);
    return this.get(pid);
  }

  async remove(pid) {
    await this.open();
    const transaction = this.database.transaction([PROFILE_STORE, SETTINGS_STORE, RESUME_STORE], 'readwrite');
    transaction.objectStore(PROFILE_STORE).delete(Number(pid));
    const settings = transaction.objectStore(SETTINGS_STORE);
    const defaultPid = await requestResult(settings.get('defaultPid'));
    if (defaultPid && Number(defaultPid.value) === Number(pid)) settings.delete('defaultPid');
    transaction.objectStore(RESUME_STORE).delete(Number(pid));
    await transactionDone(transaction);
  }

  async getResume(pid) {
    await this.open();
    if (!Number.isInteger(Number(pid))) return null;
    const transaction = this.database.transaction(RESUME_STORE, 'readonly');
    return (await requestResult(transaction.objectStore(RESUME_STORE).get(Number(pid)))) || null;
  }

  async getExperienceResume(pid, experience) {
    const record = await this.getResume(pid);
    const experienceId = String(experience || '');
    if (!record || !experienceId) return null;
    const saved = record.experiences?.[experienceId];
    if (saved?.sid) return { experience: experienceId, ...saved };
    // Records created before per-experience resume points are still usable.
    if (record.view === 'experience' && record.experience === experienceId && record.sid) {
      return {
        experience: experienceId,
        sid: record.sid,
        language: record.language,
        savedAt: record.savedAt
      };
    }
    return null;
  }

  async saveResume(resume) {
    await this.open();
    if (!Number.isInteger(Number(resume.pid))) throw new Error('A resume point requires a profile ID.');
    const pid = Number(resume.pid);
    const transaction = this.database.transaction(RESUME_STORE, 'readwrite');
    const store = transaction.objectStore(RESUME_STORE);
    const existing = await requestResult(store.get(pid));
    const record = {
      ...(existing || {}),
      pid,
      view: resume.view === 'experience' ? 'experience' : 'home',
      language: resume.language === 'kn' ? 'kn' : 'en',
      savedAt: resume.savedAt || new Date().toISOString(),
      experiences: { ...(existing?.experiences || {}) }
    };
    if (record.view === 'experience') {
      record.experience = String(resume.experience || '');
      record.sid = String(resume.sid || '');
      if (!record.experience || !record.sid) throw new Error('An experience resume point requires an experience and SID.');
      record.experiences[record.experience] = {
        sid: record.sid,
        language: record.language,
        savedAt: record.savedAt
      };
    } else {
      delete record.experience;
      delete record.sid;
    }
    store.put(record);
    await transactionDone(transaction);
    return record;
  }

  async defaultPid() {
    await this.open();
    const transaction = this.database.transaction(SETTINGS_STORE, 'readonly');
    const setting = await requestResult(transaction.objectStore(SETTINGS_STORE).get('defaultPid'));
    return setting ? Number(setting.value) : null;
  }

  async setDefaultPid(pid) {
    await this.open();
    const transaction = this.database.transaction(SETTINGS_STORE, 'readwrite');
    const store = transaction.objectStore(SETTINGS_STORE);
    if (pid == null) store.delete('defaultPid');
    else store.put({ key: 'defaultPid', value: Number(pid) });
    await transactionDone(transaction);
  }
}

async function resizeProfilePhoto(file) {
  if (!file) return '';
  if (!file.type.startsWith('image/')) throw new Error('Choose an image file for the profile photo.');
  const source = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error('The selected photo could not be read.'));
    reader.readAsDataURL(file);
  });
  const image = await new Promise((resolve, reject) => {
    const element = new Image();
    element.onload = () => resolve(element);
    element.onerror = () => reject(new Error('The selected photo is not a supported image.'));
    element.src = source;
  });
  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext('2d');
  const scale = Math.max(size / image.width, size / image.height);
  const width = image.width * scale;
  const height = image.height * scale;
  context.drawImage(image, (size - width) / 2, (size - height) / 2, width, height);
  return canvas.toDataURL('image/jpeg', .82);
}

// Source: js/profile-ui.js
class ProfileUI {
  constructor({ store, onSelected, onCreated, onChanged }) {
    this.store = store;
    this.onSelected = onSelected;
    this.onCreated = onCreated;
    this.onChanged = onChanged;
    this.editingPid = null;
    this.photo = '';
    this.bind();
  }

  initials(profile) {
    return profile.name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase() || 'ॐ';
  }

  avatar(profile, className = 'profile-avatar') {
    if (profile.photo) {
      const image = document.createElement('img');
      image.className = className;
      image.src = profile.photo;
      image.alt = '';
      return image;
    }
    const fallback = document.createElement('span');
    fallback.className = className + ' profile-initials';
    fallback.textContent = this.initials(profile);
    return fallback;
  }

  async showSelection({ switching = false } = {}) {
    const profiles = await this.store.list();
    const defaultPid = await this.store.defaultPid();
    const list = document.getElementById('profile-list');
    list.textContent = '';
    profiles.forEach((profile) => {
      const card = document.createElement('article');
      card.className = 'profile-card';
      const select = document.createElement('button');
      select.type = 'button';
      select.className = 'profile-select';
      select.dataset.pid = profile.pid;
      select.appendChild(this.avatar(profile, 'profile-card-avatar'));
      const copy = document.createElement('span');
      copy.className = 'profile-card-copy';
      const name = document.createElement('strong');
      name.textContent = profile.name;
      const language = document.createElement('small');
      language.textContent = profile.language === 'kn' ? 'ಕನ್ನಡ' : 'English';
      copy.append(name, language);
      select.appendChild(copy);
      if (profile.pid === defaultPid) {
        const badge = document.createElement('span');
        badge.className = 'default-badge';
        badge.textContent = 'Default';
        select.appendChild(badge);
      }
      const actions = document.createElement('div');
      actions.className = 'profile-card-actions';
      actions.innerHTML = `<button type="button" data-profile-action="edit" data-pid="${profile.pid}">Edit</button><button type="button" data-profile-action="default" data-pid="${profile.pid}">${profile.pid === defaultPid ? 'Unset default' : 'Make default'}</button><button type="button" data-profile-action="delete" data-pid="${profile.pid}">Delete</button>`;
      card.append(select, actions);
      list.appendChild(card);
    });
    document.getElementById('profile-selection-title').textContent = switching ? 'Switch profile' : 'Who is using Gitaverse?';
    document.getElementById('profile-selection-back').hidden = !switching;
  }

  async showForm(profile = null) {
    this.editingPid = profile?.pid || null;
    this.photo = profile?.photo || '';
    document.getElementById('profile-form-title').textContent = profile ? 'Edit profile' : 'Create your profile';
    document.getElementById('profile-form-intro').textContent = profile
      ? 'Keep this profile’s local preferences up to date.'
      : 'Profiles keep each person’s language and experience separate on this device.';
    document.getElementById('profile-name').value = profile?.name || '';
    document.getElementById('profile-dob').value = profile?.dob || '';
    document.getElementById('profile-gender').value = profile?.gender || '';
    document.getElementById('profile-language').value = profile?.language || 'en';
    document.getElementById('profile-default').checked = profile ? (await this.store.defaultPid()) === profile.pid : true;
    document.getElementById('profile-form-cancel').hidden = !profile;
    document.getElementById('profile-form-error').textContent = '';
    this.renderPhotoPreview(profile);
  }

  renderPhotoPreview(profile = null) {
    const preview = document.getElementById('profile-photo-preview');
    preview.textContent = '';
    preview.appendChild(this.avatar({ name: document.getElementById('profile-name').value || profile?.name || '', photo: this.photo }, 'profile-photo-avatar'));
    document.getElementById('profile-photo-remove').hidden = !this.photo;
  }

  async renderPills(profile) {
    document.querySelectorAll('[data-profile-pill]').forEach((button) => {
      button.textContent = '';
      button.appendChild(this.avatar(profile, 'profile-pill-avatar'));
      const name = document.createElement('span');
      name.textContent = profile.name;
      button.appendChild(name);
      button.dataset.pid = profile.pid;
      button.setAttribute('aria-label', 'Profile: ' + profile.name + '. Open profile options.');
    });
  }

  bind() {
    document.getElementById('profile-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      const error = document.getElementById('profile-form-error');
      error.textContent = '';
      try {
        const dob = document.getElementById('profile-dob').value;
        if (!dob || new Date(dob + 'T00:00:00') > new Date()) throw new Error('Enter a valid date of birth.');
        const profile = await this.store.save({
          pid: this.editingPid,
          name: document.getElementById('profile-name').value,
          dob,
          gender: document.getElementById('profile-gender').value,
          language: document.getElementById('profile-language').value,
          photo: this.photo,
          analyticsConsent: true
        });
        if (document.getElementById('profile-default').checked) await this.store.setDefaultPid(profile.pid);
        else if ((await this.store.defaultPid()) === profile.pid) await this.store.setDefaultPid(null);
        if (this.editingPid) await this.onChanged(profile);
        else await this.onCreated(profile);
      } catch (failure) {
        error.textContent = failure.message || 'The profile could not be saved.';
      }
    });
    document.getElementById('profile-name').addEventListener('input', () => this.renderPhotoPreview());
    document.getElementById('profile-photo').addEventListener('change', async (event) => {
      const error = document.getElementById('profile-form-error');
      try {
        this.photo = await resizeProfilePhoto(event.target.files?.[0]);
        this.renderPhotoPreview();
      } catch (failure) { error.textContent = failure.message; }
    });
    document.getElementById('profile-photo-remove').addEventListener('click', () => {
      this.photo = '';
      document.getElementById('profile-photo').value = '';
      this.renderPhotoPreview();
    });
    document.getElementById('profile-list').addEventListener('click', async (event) => {
      const select = event.target.closest('.profile-select');
      if (select) return this.onSelected(await this.store.get(select.dataset.pid));
      const action = event.target.closest('[data-profile-action]');
      if (!action) return;
      const profile = await this.store.get(action.dataset.pid);
      if (action.dataset.profileAction === 'edit') return this.onChanged(profile, { edit: true });
      if (action.dataset.profileAction === 'default') {
        const current = await this.store.defaultPid();
        await this.store.setDefaultPid(current === profile.pid ? null : profile.pid);
        return this.showSelection({ switching: true });
      }
      if (action.dataset.profileAction === 'delete' && window.confirm('Delete the profile “' + profile.name + '” from this device?')) {
        await this.store.remove(profile.pid);
        const remaining = await this.store.list();
        if (!remaining.length) return this.onChanged(null, { setup: true });
        return this.onChanged(null, { deletedPid: profile.pid, remaining });
      }
    });
  }
}

// Source: js/events/event-schema.js
const EVENT_SCHEMA_VERSION = 1;

const EVENT_NAMES = new Set([
  'app_opened',
  'profile_created',
  'profile_selected',
  'profile_updated',
  'profile_switched',
  'experience_selected',
  'location_changed',
  'language_changed',
  'home_opened',
  'data_load_failed',
  'profile_storage_failed',
  'verse_viewed',
  'verse_engaged_10s',
  'verse_engaged_30s',
  'verse_engaged_60s',
  'audio_started',
  'audio_resumed',
  'audio_paused',
  'audio_seeked',
  'audio_25',
  'audio_50',
  'audio_75',
  'audio_completed',
  'audio_failed',
  'rachana_opened',
  'rachana_page_viewed',
  'rachana_navigation_opened',
  'rachana_profile_selected',
  'rachana_about_opened',
  'rachana_gitaverse_opened',
  'rachana_document_failed'
]);

function validateEventInput(name, input = {}) {
  if (!EVENT_NAMES.has(name)) throw new Error('Unknown Gitaverse event: ' + name);
  if (input.context != null && (typeof input.context !== 'object' || Array.isArray(input.context))) {
    throw new Error('Event context must be an object.');
  }
  if (input.details != null && (typeof input.details !== 'object' || Array.isArray(input.details))) {
    throw new Error('Event details must be an object.');
  }
  if (name === 'location_changed') {
    if (!input.context?.experience || !input.context?.sid) {
      throw new Error('location_changed requires experience and sid.');
    }
  }
  if ((name === 'location_changed' || name === 'home_opened') && !Number.isInteger(Number(input.profileId))) {
    throw new Error(name + ' requires a profile ID.');
  }
}

function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  Object.values(value).forEach(deepFreeze);
  return Object.freeze(value);
}

// Source: js/events/profile-analytics.js
const GENDERS = new Set(['female', 'male', 'nonbinary', 'self-described']);

function validDateParts(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value || ''));
  if (!match) return null;
  const [, year, month, day] = match.map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) return null;
  return { year, month, day };
}

function ageBand(dob, now = new Date()) {
  const birth = validDateParts(dob);
  if (!birth || Number.isNaN(now.getTime())) return 'missing';
  let age = now.getUTCFullYear() - birth.year;
  const month = now.getUTCMonth() + 1;
  const day = now.getUTCDate();
  if (month < birth.month || (month === birth.month && day < birth.day)) age -= 1;
  if (age < 0) return 'missing';
  if (age < 13) return 'unknown';
  if (age < 18) return '13-17';
  if (age < 25) return '18-24';
  if (age < 35) return '25-34';
  if (age < 45) return '35-44';
  if (age < 55) return '45-54';
  if (age < 65) return '55-64';
  if (age < 75) return '65-74';
  return '75-plus';
}

function profileAnalyticsContext(profile, now = new Date()) {
  if (!profile) return {};
  return {
    ageBand: ageBand(profile.dob, now),
    genderGroup: GENDERS.has(profile.gender) ? profile.gender.replace('-', '_') : 'not_said',
    profileLanguage: profile.language === 'kn' ? 'kn' : 'en'
  };
}

// Source: js/events/event-bus.js
function randomId() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') return globalThis.crypto.randomUUID();
  const bytes = new Uint8Array(16);
  globalThis.crypto.getRandomValues(bytes);
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
}

class EventBus {
  constructor({ appVersion = 'dev', contextProvider = () => ({}), onAdapterError = () => {} } = {}) {
    this.appVersion = appVersion;
    this.contextProvider = contextProvider;
    this.onAdapterError = onAdapterError;
    this.sessionId = randomId();
    this.adapters = new Map();
  }

  subscribe(adapter) {
    if (!adapter?.id || typeof adapter.handle !== 'function') throw new Error('An event adapter requires an ID and handle function.');
    if (this.adapters.has(adapter.id)) throw new Error('Event adapter already registered: ' + adapter.id);
    this.adapters.set(adapter.id, adapter);
    return () => this.adapters.delete(adapter.id);
  }

  emit(name, input = {}) {
    validateEventInput(name, input);
    const event = deepFreeze({
      schemaVersion: EVENT_SCHEMA_VERSION,
      eventId: randomId(),
      event: name,
      occurredAt: new Date().toISOString(),
      sessionId: this.sessionId,
      profileId: input.profileId == null ? null : Number(input.profileId),
      anonymousProfileId: input.anonymousProfileId || null,
      context: {
        appVersion: this.appVersion,
        ...this.contextProvider(),
        ...(input.context || {})
      },
      details: { ...(input.details || {}) }
    });

    this.adapters.forEach((adapter) => {
      if (adapter.accepts && !adapter.accepts(event)) return;
      try {
        Promise.resolve(adapter.handle(event)).catch((error) => this.reportAdapterError(adapter, error, event));
      } catch (error) {
        this.reportAdapterError(adapter, error, event);
      }
    });
    return event;
  }

  reportAdapterError(adapter, error, event) {
    try { this.onAdapterError({ adapter: adapter.id, error, event }); } catch (_) {}
  }
}

// Source: js/events/resume-adapter.js
class ResumeAdapter {
  constructor({ store }) {
    this.id = 'resume';
    this.store = store;
  }

  accepts(event) {
    return event.event === 'location_changed' || event.event === 'home_opened';
  }

  handle(event) {
    const base = {
      pid: event.profileId,
      language: event.context.language === 'kn' ? 'kn' : 'en',
      savedAt: event.occurredAt
    };
    if (event.event === 'home_opened') {
      return this.store.saveResume({ ...base, view: 'home' });
    }
    return this.store.saveResume({
      ...base,
      view: 'experience',
      experience: event.context.experience,
      sid: event.context.sid
    });
  }
}

// Source: js/events/clarity-adapter.js
class ClarityAdapter {
  constructor({ projectId = '', target = globalThis, documentRef = globalThis.document } = {}) {
    this.id = 'clarity';
    this.projectId = String(projectId || '').trim();
    this.target = target;
    this.document = documentRef;
    this.enabled = /^[a-z0-9]+$/i.test(this.projectId);
    this.started = false;
    this.tags = new Map();
  }

  accepts(event) {
    return this.enabled && Boolean(event.context.ageBand);
  }

  start() {
    if (this.started) return;
    this.started = true;
    const clarity = this.target.clarity = this.target.clarity || function clarityQueue() {
      (clarity.q = clarity.q || []).push(arguments);
    };
    if (this.document?.querySelector(`script[data-clarity-project="${this.projectId}"]`)) return;
    const script = this.document.createElement('script');
    script.async = true;
    script.dataset.clarityProject = this.projectId;
    script.src = `https://www.clarity.ms/tag/${encodeURIComponent(this.projectId)}`;
    this.document.head.appendChild(script);
  }

  setTag(key, value) {
    if (value == null || value === '' || this.tags.get(key) === String(value)) return;
    this.tags.set(key, String(value));
    this.target.clarity('set', key, String(value));
  }

  handle(event) {
    this.start();
    const tags = {
      age_band: event.context.ageBand,
      gender_group: event.context.genderGroup,
      profile_language: event.context.profileLanguage,
      experience: event.context.experience,
      content_language: event.context.language,
      app_version: event.context.appVersion,
      display_mode: event.context.displayMode,
      surface: event.context.surface,
      rachana_page: event.context.documentationPage
    };
    Object.entries(tags).forEach(([key, value]) => this.setTag(key, value));

    const eventName = this.eventName(event);
    if (eventName) this.target.clarity('event', eventName);
  }

  eventName(event) {
    if (event.event === 'location_changed') {
      const sourceEvents = { next: 'next_verse', previous: 'previous_verse', swipe: 'verse_swiped', goto: 'goto_verse', chapter: 'chapter_selected', resume: 'experience_resumed' };
      return sourceEvents[event.details.source] || null;
    }
    const allowed = new Set([
      'app_opened', 'profile_created', 'profile_selected', 'profile_updated', 'profile_switched',
      'experience_selected', 'language_changed', 'home_opened', 'data_load_failed', 'profile_storage_failed',
      'verse_viewed', 'verse_engaged_10s', 'verse_engaged_30s', 'verse_engaged_60s',
      'audio_started', 'audio_resumed', 'audio_paused', 'audio_seeked', 'audio_25', 'audio_50',
      'audio_75', 'audio_completed', 'audio_failed',
      'rachana_opened', 'rachana_page_viewed', 'rachana_navigation_opened', 'rachana_profile_selected',
      'rachana_about_opened', 'rachana_gitaverse_opened', 'rachana_document_failed'
    ]);
    return allowed.has(event.event) ? event.event : null;
  }
}

