// Source: js/pwa.js
class PwaManager {
  constructor({ appVersion }) {
    this.appVersion = appVersion;
    this.registration = null;
    this.installPrompt = null;
    this.reloading = false;
    this.updateNotice = document.getElementById('pwa-update-notice');
    this.statusNotice = document.getElementById('pwa-status-notice');
    this.installButtons = Array.from(document.querySelectorAll('[data-install]'));
    this.bind();
  }

  bind() {
    window.addEventListener('beforeinstallprompt', (event) => {
      event.preventDefault();
      this.installPrompt = event;
      this.installButtons.forEach((button) => { button.hidden = false; });
    });
    window.addEventListener('appinstalled', () => {
      this.installPrompt = null;
      this.installButtons.forEach((button) => { button.hidden = true; });
    });
    this.installButtons.forEach((button) => button.addEventListener('click', () => this.install()));
    document.getElementById('pwa-update-action').addEventListener('click', () => this.applyUpdate());
    document.getElementById('pwa-update-dismiss').addEventListener('click', () => { this.updateNotice.hidden = true; });
  }

  async start() {
    if (this.appVersion === 'dev' || !('serviceWorker' in navigator)) return;
    try {
      this.registration = await navigator.serviceWorker.register('service-worker.js', { scope: '/', updateViaCache: 'none' });
      if (this.registration.waiting && navigator.serviceWorker.controller) this.showUpdate();
      this.registration.addEventListener('updatefound', () => {
        const worker = this.registration.installing;
        worker?.addEventListener('statechange', () => {
          if (worker.state === 'installed' && navigator.serviceWorker.controller) this.showUpdate();
        });
      });
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        if (this.reloading) return;
        this.reloading = true;
        location.reload();
      });
      await this.registration.update();
    } catch (_) {
      // The regular online player remains available if PWA setup is unsupported or interrupted.
    }
  }

  showUpdate() {
    this.updateNotice.hidden = false;
  }

  applyUpdate() {
    const worker = this.registration?.waiting;
    if (!worker) return;
    document.getElementById('pwa-update-action').disabled = true;
    worker.postMessage({ type: 'SKIP_WAITING' });
  }

  async install() {
    if (!this.installPrompt) return;
    const prompt = this.installPrompt;
    this.installPrompt = null;
    this.installButtons.forEach((button) => { button.hidden = true; });
    await prompt.prompt();
    await prompt.userChoice;
  }

  showStatus(message) {
    document.getElementById('pwa-status-message').textContent = message;
    this.statusNotice.hidden = false;
    clearTimeout(this.statusTimer);
    this.statusTimer = setTimeout(() => { this.statusNotice.hidden = true; }, 5000);
  }
}

// Source: js/shared/about-dialog.js
class AboutDialog {
  constructor({ version = 'dev', onOpen = () => {} } = {}) {
    this.version = version;
    this.onOpen = onOpen;
    this.overlay = this.ensureMarkup();
    this.overlay.querySelector('[data-about-version]').textContent = version;
    this.overlay.querySelector('[data-about-close]').addEventListener('click', () => this.close());
    this.overlay.addEventListener('click', (event) => { if (event.target === this.overlay) this.close(); });
  }

  ensureMarkup() {
    const existing = document.getElementById('about-overlay');
    if (existing) {
      const version = existing.querySelector('#about-version');
      if (version) version.dataset.aboutVersion = '';
      const close = existing.querySelector('.about-close');
      if (close) close.dataset.aboutClose = '';
      return existing;
    }
    const overlay = document.createElement('div');
    overlay.className = 'overlay';
    overlay.id = 'about-overlay';
    overlay.hidden = true;
    overlay.innerHTML = `
      <section class="dialog about-dialog" role="dialog" aria-modal="true" aria-labelledby="about-title">
        <button class="icon-button about-close" type="button" data-about-close aria-label="Close">×</button>
        <div class="about-body">
          <div class="about-flute" aria-hidden="true"><img src="assets/images/krishna-flute.svg" alt=""><i class="about-note about-note-one">♪</i><i class="about-note about-note-two">♫</i><i class="about-note about-note-three">♩</i></div>
          <h2 id="about-title">About Gitaverse</h2>
          <p>Gitaverse is a verse and chanting experience from Gita Jyoti—a simple space to listen to, study and remain close to the Bhagavad Gita.</p>
          <div class="about-links"><a href="https://gitajyoti.org/" target="_blank" rel="noopener">Gita Jyoti</a><a href="https://lightoftheself.org/" target="_blank" rel="noopener">Light of the Self Foundation</a></div>
          <p class="about-version">Version <span data-about-version>dev</span></p>
        </div>
      </section>`;
    document.body.appendChild(overlay);
    return overlay;
  }

  open(opener = document.activeElement) {
    this.opener = opener;
    this.overlay.hidden = false;
    this.onOpen();
    requestAnimationFrame(() => this.overlay.querySelector('[data-about-close]')?.focus());
  }

  close({ restoreFocus = true } = {}) {
    if (this.overlay.hidden) return false;
    this.overlay.hidden = true;
    if (restoreFocus) this.opener?.focus?.();
    return true;
  }
}

// Source: js/player/collection-data.js
const COLLECTION_ROOT = 'data/collections';

const MASTER_HEADERS = {
  sa: ['cid', 'snum', 'sid', 'chapter_name', 'shloka', 'word_by_word', 'meaning', 'word_by_word_meaning'],
  en: ['cid', 'snum', 'sid', 'chapter_name', 'transliteration', 'meaning', 'word_by_word_meaning'],
  kn: ['cid', 'snum', 'sid', 'chapter_name', 'transliteration', 'meaning', 'word_by_word_meaning']
};

function decode(value) {
  return String(value ?? '').replace(/\\n/g, '\n');
}

function encode(value) {
  const encoded = String(value ?? '').replace(/\r\n?/g, '\n').replace(/\n/g, '\\n');
  if (encoded.includes('#')) throw new Error('The # character is not allowed in collection data.');
  return encoded;
}

function parseCollectionTable(text, expectedHeaders, label = 'collection data') {
  const lines = String(text || '').replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n').split('\n').filter((line) => line.length);
  if (!lines.length) throw new Error(label + ' is empty.');
  const headers = lines.shift().split('#');
  if (expectedHeaders && headers.join('#') !== expectedHeaders.join('#')) {
    throw new Error(label + ' header does not match its collection contract.');
  }
  const seen = new Set();
  const rows = lines.map((line, index) => {
    const fields = line.split('#');
    if (fields.length !== headers.length) throw new Error(label + ' row ' + (index + 2) + ' has an invalid field count.');
    const row = Object.fromEntries(headers.map((header, fieldIndex) => [header, decode(fields[fieldIndex])]));
    if (row.sid) {
      if (row.sid !== row.cid + '.' + row.snum && 'cid' in row) throw new Error(label + ' contains an invalid SID: ' + row.sid);
      const key = row.order ? row.sid + ':' + row.order : row.sid;
      if (seen.has(key)) throw new Error(label + ' contains duplicate key ' + key + '.');
      seen.add(key);
    }
    return row;
  });
  return { headers, rows };
}

async function fetchText(url, version) {
  const request = new URL(url, location.href);
  if (version) request.searchParams.set('v', version);
  const response = await fetch(request.href);
  if (!response.ok) throw new Error('Could not load ' + url + ' (HTTP ' + response.status + ').');
  return response.text();
}

async function fetchTable(url, expectedHeaders, version) {
  return parseCollectionTable(await fetchText(url, version), expectedHeaders, url);
}

function registryEntry(registry, id, label) {
  const entry = registry.rows.find((row) => row.collection_id === id);
  if (!entry) throw new Error(label + ' collection was not found: ' + id + '.');
  return entry;
}

function catalogEntry(catalog, type, label) {
  const entry = catalog.rows.find((row) => row.content_type === type);
  if (!entry) throw new Error(label + ' catalog does not define ' + type + '.');
  return entry.content_url;
}

function languageFile(catalog, language) {
  const entry = catalog.rows.find((row) => row.language === language && row.content_type === 'master');
  if (!entry) throw new Error('Verse collection does not define master data for ' + language + '.');
  return entry.content_url;
}

function verifyIdentity(reference, candidate, label) {
  if (reference.rows.length !== candidate.rows.length) throw new Error(label + ' does not contain the canonical SID count.');
  reference.rows.forEach((row, index) => {
    const other = candidate.rows[index];
    if (!other || row.cid !== other.cid || row.snum !== other.snum || row.sid !== other.sid) {
      throw new Error(label + ' differs from the canonical SID sequence at row ' + (index + 2) + '.');
    }
  });
}

function mediaKey(sid, order) {
  return sid + ':' + order;
}

function normalizeCollectionData({ sa, en, kn, audioComposition, imageComposition, audioCatalogs, imageCatalogs, experience, resolveMediaUrl = (url) => url }) {
  for (const [label, table] of [['English master', en], ['Kannada master', kn], ['Gita-700 audio composition', audioComposition], ['Gita-700 image composition', imageComposition]]) {
    verifyIdentity(sa, table, label);
  }
  const bySid = (table) => new Map(table.rows.map((row) => [row.sid, row]));
  const enBySid = bySid(en);
  const knBySid = bySid(kn);
  const audioBySid = bySid(audioComposition);
  const imageBySid = bySid(imageComposition);
  const rows = sa.rows.map((sourceRow) => {
    const enRow = enBySid.get(sourceRow.sid);
    const knRow = knBySid.get(sourceRow.sid);
    const audioRef = audioBySid.get(sourceRow.sid);
    const imageRef = imageBySid.get(sourceRow.sid);
    let chantFullSaUrl = '';
    if (audioRef.chant_full_sa_collection || audioRef.chant_full_sa_order) {
      if (!audioRef.chant_full_sa_collection || !audioRef.chant_full_sa_order) throw new Error('Incomplete audio reference at ' + sourceRow.sid + '.');
      const catalog = audioCatalogs.get(audioRef.chant_full_sa_collection);
      const asset = catalog?.rows.find((row) => mediaKey(row.sid, row.order) === mediaKey(sourceRow.sid, audioRef.chant_full_sa_order));
      if (!asset) throw new Error('Audio reference does not resolve at ' + sourceRow.sid + '.');
      chantFullSaUrl = resolveMediaUrl(asset.audio_url);
    }
    let chapterIconUrl = '';
    if (imageRef.chapter_icon_collection || imageRef.chapter_icon_order) {
      if (!imageRef.chapter_icon_collection || !imageRef.chapter_icon_order) throw new Error('Incomplete image reference at ' + sourceRow.sid + '.');
      const catalog = imageCatalogs.get(imageRef.chapter_icon_collection);
      const asset = catalog?.rows.find((row) => mediaKey(row.sid, row.order) === mediaKey(sourceRow.sid, imageRef.chapter_icon_order));
      if (!asset) throw new Error('Image reference does not resolve at ' + sourceRow.sid + '.');
      chapterIconUrl = resolveMediaUrl(asset.image_url);
    }
    return {
      cid: sourceRow.cid,
      snum: sourceRow.snum,
      sid: sourceRow.sid,
      source: {
        chapterName: sourceRow.chapter_name,
        shloka: sourceRow.shloka,
        wordByWord: sourceRow.word_by_word,
        meaning: sourceRow.meaning,
        wordByWordMeaning: sourceRow.word_by_word_meaning
      },
      languages: {
        en: { chapterName: enRow.chapter_name, transliteration: enRow.transliteration, meaning: enRow.meaning, wordByWordMeaning: enRow.word_by_word_meaning },
        kn: { chapterName: knRow.chapter_name, transliteration: knRow.transliteration, meaning: knRow.meaning, wordByWordMeaning: knRow.word_by_word_meaning }
      },
      media: { chantFullSaUrl, chapterIconUrl }
    };
  });
  return { schemaVersion: 2, experience, rows };
}

async function loadMediaCatalogs(type, composition, collectionField, headers, version) {
  const collectionIds = new Set(composition.rows.map((row) => row[collectionField]).filter(Boolean));
  const registry = await fetchTable(COLLECTION_ROOT + '/' + type + '/collection.csv', null, version);
  const catalogs = new Map();
  for (const id of collectionIds) {
    const entry = registryEntry(registry, id, type);
    catalogs.set(id, await fetchTable(entry.catalog_url, headers, version));
  }
  return catalogs;
}

async function loadCollectionExperience(experienceId, { version = '' } = {}) {
  const experienceRegistry = await fetchTable(COLLECTION_ROOT + '/experiences/collection.csv', null, version);
  const experienceEntry = registryEntry(experienceRegistry, experienceId, 'Experience');
  const experienceCatalog = await fetchTable(experienceEntry.catalog_url, ['content_type', 'content_url'], version);
  const configurationUrl = catalogEntry(experienceCatalog, 'configuration', experienceId);
  const configurationResponse = await fetchText(configurationUrl, version);
  const experience = JSON.parse(configurationResponse);
  if (experience.id !== experienceId || experience.schemaVersion !== 1) throw new Error('Unsupported experience configuration for ' + experienceId + '.');

  const verseRegistry = await fetchTable(COLLECTION_ROOT + '/verses/collection.csv', null, version);
  const verseEntry = registryEntry(verseRegistry, experience.verseCollection, 'Verse');
  const verseCatalog = await fetchTable(verseEntry.catalog_url, ['language', 'content_type', 'content_url'], version);
  const [sa, en, kn, audioComposition, imageComposition] = await Promise.all([
    fetchTable(languageFile(verseCatalog, 'sa'), MASTER_HEADERS.sa, version),
    fetchTable(languageFile(verseCatalog, 'en'), MASTER_HEADERS.en, version),
    fetchTable(languageFile(verseCatalog, 'kn'), MASTER_HEADERS.kn, version),
    fetchTable(catalogEntry(experienceCatalog, 'audio', experienceId), ['cid', 'snum', 'sid', 'chant_full_sa_collection', 'chant_full_sa_order'], version),
    fetchTable(catalogEntry(experienceCatalog, 'images', experienceId), ['cid', 'snum', 'sid', 'chapter_icon_collection', 'chapter_icon_order'], version)
  ]);
  const [audioCatalogs, imageCatalogs] = await Promise.all([
    loadMediaCatalogs('audio', audioComposition, 'chant_full_sa_collection', ['sid', 'order', 'language', 'audio_url'], version),
    loadMediaCatalogs('images', imageComposition, 'chapter_icon_collection', ['sid', 'order', 'image_url'], version)
  ]);
  return normalizeCollectionData({ sa, en, kn, audioComposition, imageComposition, audioCatalogs, imageCatalogs, experience });
}

function selectedCollectionFiles(fileList) {
  const files = new Map();
  for (const file of Array.from(fileList || [])) {
    const original = String(file.webkitRelativePath || file.name).replace(/\\/g, '/');
    const marker = original.indexOf('collections/');
    const relative = marker >= 0 ? original.slice(marker + 'collections/'.length) : original.replace(/^\/+/, '');
    files.set(COLLECTION_ROOT + '/' + relative, file);
  }
  return files;
}

async function loadCollectionExperienceWithReader(experienceId, { text, resolveMediaUrl, onLanguageFile = () => {} }) {
  const table = async (url, headers = null) => parseCollectionTable(await text(url), headers, url);
  const experienceRegistry = await table(COLLECTION_ROOT + '/experiences/collection.csv');
  const experienceEntry = registryEntry(experienceRegistry, experienceId, 'Experience');
  const experienceCatalog = await table(experienceEntry.catalog_url, ['content_type', 'content_url']);
  const experience = JSON.parse(await text(catalogEntry(experienceCatalog, 'configuration', experienceId)));
  if (experience.id !== experienceId || experience.schemaVersion !== 1) throw new Error('Unsupported experience configuration for ' + experienceId + '.');
  const verseRegistry = await table(COLLECTION_ROOT + '/verses/collection.csv');
  const verseEntry = registryEntry(verseRegistry, experience.verseCollection, 'Verse');
  const verseCatalog = await table(verseEntry.catalog_url, ['language', 'content_type', 'content_url']);
  const languageUrls = Object.fromEntries(['sa', 'en', 'kn'].map((language) => [language, languageFile(verseCatalog, language)]));
  Object.entries(languageUrls).forEach(([language, url]) => onLanguageFile(language, url));
  const [sa, en, kn, audioComposition, imageComposition] = await Promise.all([
    table(languageUrls.sa, MASTER_HEADERS.sa),
    table(languageUrls.en, MASTER_HEADERS.en),
    table(languageUrls.kn, MASTER_HEADERS.kn),
    table(catalogEntry(experienceCatalog, 'audio', experienceId), ['cid', 'snum', 'sid', 'chant_full_sa_collection', 'chant_full_sa_order']),
    table(catalogEntry(experienceCatalog, 'images', experienceId), ['cid', 'snum', 'sid', 'chapter_icon_collection', 'chapter_icon_order'])
  ]);
  async function localCatalogs(type, composition, collectionField, headers) {
    const registry = await table(COLLECTION_ROOT + '/' + type + '/collection.csv');
    const catalogs = new Map();
    for (const id of new Set(composition.rows.map((row) => row[collectionField]).filter(Boolean))) {
      catalogs.set(id, await table(registryEntry(registry, id, type).catalog_url, headers));
    }
    return catalogs;
  }
  const [audioCatalogs, imageCatalogs] = await Promise.all([
    localCatalogs('audio', audioComposition, 'chant_full_sa_collection', ['sid', 'order', 'language', 'audio_url']),
    localCatalogs('images', imageComposition, 'chapter_icon_collection', ['sid', 'order', 'image_url'])
  ]);
  return normalizeCollectionData({ sa, en, kn, audioComposition, imageComposition, audioCatalogs, imageCatalogs, experience, resolveMediaUrl });
}

async function loadCollectionExperienceFromFiles(experienceId, fileList) {
  const files = selectedCollectionFiles(fileList);
  if (!files.size) throw new Error('Choose the data/collections folder.');
  const text = async (url) => {
    const file = files.get(url);
    if (!file) throw new Error('The selected folder is missing ' + url + '.');
    return file.text();
  };
  const objectUrls = new Map();
  const resolveMediaUrl = (url) => {
    const file = files.get(url);
    if (!file) throw new Error('The selected folder is missing media file ' + url + '.');
    if (!objectUrls.has(url)) objectUrls.set(url, URL.createObjectURL(file));
    return objectUrls.get(url);
  };
  return loadCollectionExperienceWithReader(experienceId, { text, resolveMediaUrl });
}

function relativeCollectionPath(url) {
  const prefix = COLLECTION_ROOT + '/';
  if (!String(url).startsWith(prefix)) throw new Error('Collection path is outside data/collections: ' + url + '.');
  return String(url).slice(prefix.length);
}

async function fileHandleAt(rootHandle, url) {
  const parts = relativeCollectionPath(url).split('/').filter(Boolean);
  const filename = parts.pop();
  let directory = rootHandle;
  for (const part of parts) directory = await directory.getDirectoryHandle(part);
  return directory.getFileHandle(filename);
}

class WritableCollectionWorkspace {
  constructor(rootHandle) {
    this.rootHandle = rootHandle;
    this.languageFiles = new Map();
    this.baselines = new Map();
    this.objectUrls = new Map();
  }

  async readFile(url) {
    try {
      return await (await fileHandleAt(this.rootHandle, url)).getFile();
    } catch (error) {
      throw new Error('The selected collections folder is missing ' + relativeCollectionPath(url) + '.');
    }
  }

  async readText(url) {
    return (await this.readFile(url)).text();
  }

  async load(experienceId) {
    this.languageFiles.clear();
    this.baselines.clear();
    const dataset = await loadCollectionExperienceWithReader(experienceId, {
      text: async (url) => {
        const value = await this.readText(url);
        if ([...this.languageFiles.values()].includes(url)) this.baselines.set(url, value);
        return value;
      },
      onLanguageFile: (language, url) => this.languageFiles.set(language, url),
      resolveMediaUrl: (url) => {
        if (!this.objectUrls.has(url)) {
          const promise = this.readFile(url).then((file) => URL.createObjectURL(file));
          this.objectUrls.set(url, promise);
        }
        return this.objectUrls.get(url);
      }
    });
    for (const row of dataset.rows) {
      for (const field of ['chantFullSaUrl', 'chapterIconUrl']) {
        if (row.media[field] instanceof Promise) row.media[field] = await row.media[field];
      }
    }
    return dataset;
  }

  async saveLanguageMasters(dataset, languages) {
    const pending = [];
    for (const language of [...new Set(languages)].sort()) {
      const url = this.languageFiles.get(language);
      if (!url) throw new Error('The workspace does not define master data for ' + language + '.');
      const handle = await fileHandleAt(this.rootHandle, url);
      const current = await (await handle.getFile()).text();
      if (current !== this.baselines.get(url)) {
        const error = new Error('The local ' + url.split('/').pop() + ' changed outside Gitaverse. Reload the collections folder before saving.');
        error.code = 'WORKSPACE_CONFLICT';
        throw error;
      }
      pending.push({ language, url, handle, content: serializeLanguageMaster(dataset, language) });
    }
    for (const entry of pending) {
      const writable = await entry.handle.createWritable();
      await writable.write(entry.content);
      await writable.close();
      const verified = await (await entry.handle.getFile()).text();
      if (verified !== entry.content) throw new Error('Could not verify the saved ' + entry.url.split('/').pop() + '.');
      this.baselines.set(entry.url, verified);
    }
    return pending.map((entry) => entry.url.split('/').pop());
  }
}

async function openWritableCollectionWorkspace(experienceId, directoryHandle) {
  if (!directoryHandle || directoryHandle.kind !== 'directory') throw new Error('Choose the data/collections folder.');
  const workspace = new WritableCollectionWorkspace(directoryHandle);
  const dataset = await workspace.load(experienceId);
  return { dataset, workspace };
}

function serializeLanguageMaster(dataset, language) {
  const headers = MASTER_HEADERS[language];
  if (!headers) throw new Error('Unsupported language master: ' + language + '.');
  const rows = dataset.rows.map((row) => {
    if (language === 'sa') {
      return [row.cid, row.snum, row.sid, row.source.chapterName, row.source.shloka, row.source.wordByWord, row.source.meaning, row.source.wordByWordMeaning];
    }
    const content = row.languages[language];
    return [row.cid, row.snum, row.sid, content.chapterName, content.transliteration, content.meaning, content.wordByWordMeaning];
  });
  return [headers, ...rows].map((row) => row.map(encode).join('#')).join('\n') + '\n';
}

// Source: js/player/audio-player.js
class AudioPlayer {
  constructor({ audio, playButton, playIcon, pauseIcon, seek, time, onError = () => {}, onEvent = () => {} }) {
    this.audio = audio;
    this.playButton = playButton;
    this.playIcon = playIcon;
    this.pauseIcon = pauseIcon;
    this.seek = seek;
    this.time = time;
    this.onError = onError;
    this.onEvent = onEvent;
    this.started = false;
    this.suppressPause = false;
    this.milestones = new Set();
    this.listenedSeconds = 0;
    this.lastPlaybackTime = 0;
    this.bind();
  }

  bind() {
    this.playButton.addEventListener('click', () => this.toggle());
    this.audio.addEventListener('play', () => {
      this.onEvent(this.started ? 'audio_resumed' : 'audio_started');
      this.started = true;
      this.updatePlayState();
    });
    this.audio.addEventListener('pause', () => {
      if (!this.suppressPause && this.started && !this.audio.ended && this.audio.currentTime > 0) this.onEvent('audio_paused');
      this.updatePlayState();
    });
    this.audio.addEventListener('ended', () => {
      this.onEvent('audio_completed');
      this.updatePlayState();
    });
    this.audio.addEventListener('loadedmetadata', () => {
      this.seek.max = Number.isFinite(this.audio.duration) ? String(this.audio.duration) : '0';
      this.seek.disabled = !Number.isFinite(this.audio.duration) || this.audio.duration <= 0;
      this.time.textContent = '00:00 / ' + this.formatTime(this.audio.duration);
    });
    this.audio.addEventListener('timeupdate', () => {
      const currentTime = this.audio.currentTime || 0;
      const playbackDelta = currentTime - this.lastPlaybackTime;
      if (!this.audio.paused && playbackDelta > 0 && playbackDelta < 2) this.listenedSeconds += playbackDelta;
      this.lastPlaybackTime = currentTime;
      this.seek.value = String(this.audio.currentTime || 0);
      this.time.textContent = this.formatTime(this.audio.currentTime) + ' / ' + this.formatTime(this.audio.duration);
      if (Number.isFinite(this.audio.duration) && this.audio.duration > 0) {
        const progress = this.listenedSeconds / this.audio.duration;
        [[.25, 'audio_25'], [.5, 'audio_50'], [.75, 'audio_75']].forEach(([point, name]) => {
          if (progress >= point && !this.milestones.has(name)) {
            this.milestones.add(name);
            this.onEvent(name);
          }
        });
      }
    });
    this.seek.addEventListener('input', (event) => {
      if (Number.isFinite(this.audio.duration)) this.audio.currentTime = Number(event.target.value);
    });
    this.seek.addEventListener('change', () => {
      this.lastPlaybackTime = this.audio.currentTime || 0;
      this.onEvent('audio_seeked');
    });
    this.audio.addEventListener('error', () => {
      this.time.textContent = 'Audio unavailable';
      this.playButton.disabled = true;
      this.seek.disabled = true;
      this.updatePlayState();
      this.onError();
      this.onEvent('audio_failed');
    });
  }

  setSource(source) {
    this.suppressPause = true;
    this.stop();
    this.suppressPause = false;
    this.started = false;
    this.milestones.clear();
    this.listenedSeconds = 0;
    this.lastPlaybackTime = 0;
    this.audio.removeAttribute('src');
    if (source) this.audio.src = source;
    this.playButton.disabled = !source;
    this.seek.disabled = !source;
    this.seek.max = '0';
    this.seek.value = '0';
    this.time.textContent = source ? '00:00 / 00:00' : 'No audio';
  }

  toggle() {
    if (!this.audio.getAttribute('src')) return;
    if (this.audio.paused) this.audio.play().catch(() => this.updatePlayState());
    else this.audio.pause();
  }

  stop() {
    this.audio.pause();
    this.audio.currentTime = 0;
    this.seek.value = '0';
    this.updatePlayState();
  }

  updatePlayState() {
    const playing = !this.audio.paused && !this.audio.ended;
    this.playIcon.toggleAttribute('hidden', playing);
    this.pauseIcon.toggleAttribute('hidden', !playing);
    this.playButton.setAttribute('aria-label', playing ? 'Pause audio' : 'Play audio');
    this.playButton.title = (playing ? 'Pause audio' : 'Play audio') + ' (P or Space)';
  }

  formatTime(seconds) {
    if (!Number.isFinite(seconds)) return '00:00';
    const minutes = Math.floor(seconds / 60);
    const remainder = Math.floor(seconds % 60);
    return String(minutes).padStart(2, '0') + ':' + String(remainder).padStart(2, '0');
  }
}

// Source: js/player/renderers/gita-700.js
const PANELS = [
  { role: 'shloka', panelClass: 'shloka', max: [42, 36], min: 10 },
  { role: 'meaning', panelClass: 'meaning', max: [31, 27], min: 10 },
  { role: 'transliteration', panelClass: 'transliteration', max: [30, 27], min: 10 },
  { role: 'word', panelClass: 'word', max: [22, 19], min: 9 }
];

function createGita700Renderer() {
  let root;
  let editing = false;

  function fieldFor(role, language) {
    if (role === 'shloka') return 'source.shloka';
    if (role === 'word') return 'languages.' + language + '.wordByWordMeaning';
    return 'languages.' + language + '.' + role;
  }

  function fieldValue(row, field) {
    return field.split('.').reduce((value, part) => value && value[part], row) || '';
  }

  function mount(container) {
    root = container;
    root.innerHTML = '<div class="gita-700-panels">' + PANELS.map((panel) =>
      '<article class="gita-700-panel gita-700-panel-' + panel.panelClass + '">' +
        '<div class="gita-700-panel-content" data-panel="' + panel.role + '">' +
          '<div class="gita-700-text" data-role="' + panel.role + '"></div>' +
        '</div>' +
      '</article>'
    ).join('') + '</div>';
  }

  function render(row, language) {
    PANELS.forEach((panel) => {
      const field = fieldFor(panel.role, language);
      const element = root.querySelector('[data-role="' + panel.role + '"]');
      const text = fieldValue(row, field);
      element.dataset.field = field;
      element.textContent = text || '—';
      element.classList.toggle('empty', !text);
      if (editing) makeEditable(element);
    });
    if (!editing) requestAnimationFrame(fitText);
  }

  function makeEditable(element) {
    element.contentEditable = 'true';
    element.spellcheck = false;
    element.dataset.editField = element.dataset.field;
    element.classList.remove('empty');
    if (element.textContent === '—') element.textContent = '';
  }

  function setEditing(enabled) {
    editing = enabled;
    root.querySelectorAll('[data-role]').forEach((element) => {
      if (enabled) makeEditable(element);
      else {
        element.contentEditable = 'false';
        delete element.dataset.editField;
      }
    });
    if (!enabled) requestAnimationFrame(fitText);
  }

  function editableElements() {
    return Array.from(root.querySelectorAll('[data-edit-field]'));
  }

  function fitElement(panel, text, maxSize, minSize) {
    if (!panel || !text || !panel.clientHeight) return;
    let low = minSize;
    let high = maxSize;
    let best = minSize;
    while (low <= high) {
      const middle = Math.floor((low + high) / 2);
      text.style.fontSize = middle + 'px';
      if (text.scrollHeight <= panel.clientHeight - 4 && text.scrollWidth <= panel.clientWidth - 4) {
        best = middle;
        low = middle + 1;
      } else {
        high = middle - 1;
      }
    }
    text.style.fontSize = best + 'px';
  }

  function fitText() {
    if (editing || !root) return;
    const mobile = matchMedia('(max-width: 760px)').matches;
    PANELS.forEach((panel) => {
      fitElement(
        root.querySelector('[data-panel="' + panel.role + '"]'),
        root.querySelector('[data-role="' + panel.role + '"]'),
        panel.max[mobile ? 1 : 0],
        panel.min
      );
    });
  }

  return {
    id: 'gita-700',
    mount,
    render,
    setEditing,
    editableElements,
    fitText,
    destroy() { if (root) root.textContent = ''; root = null; }
  };
}

